    u8 unk39C[0x4A8 - 0x39C];
    void (*pp_tls)(struct sppp *sp);    /* 0x4A8 */
    void (*pp_tlf)(struct sppp *sp);    /* 0x4AC */
};

/* struct ifqueue (4.4BSD if.h) */
struct ifqueue {
    struct mbuf *ifq_head;      /* 0x00 */
